from colorsys import rgb_to_hls,hls_to_rgb
base=['#00a9ee','#0753d6','#2bd4c8','#001134']
def shade(hexx,l):
 r,g,b=[int(hexx[i:i+2],16)/255 for i in (1,3,5)];h,_,sat=rgb_to_hls(r,g,b);rgb=hls_to_rgb(h,l,sat);return '#'+''.join(f'{round(x*255):02x}' for x in rgb)
