# Use the reference palette as required for collection review; replica preserves the source colours exactly.
def pos(col,row,w,h):return f'grid-column:{col} / span {w}; grid-row:{row} / span {h}'
def el(root,folder,body,col=1,row=1,w=12,h=6,variant='',data=''):
 return f'<div class="{root} {variant}" data-el="{K}-{folder}" style="{pos(col,row,w,h)}{data}">{body}</div>'
def card(name,note='',fig='',mark='',on=False):
 return '<div class="card'+(' on' if on else '')+'" data-el="cyanloop-card"><div class="parts">'+(f'<span class="mark"><span class="icon" data-icon="{mark}"></span></span>' if mark else '')+(f'<p class="fig">{fig}</p>' if fig else '')+f'<p class="name">{name}</p><p class="note">{note}</p></div></div>'
def group(cards,col,row,w,h,cl=''):
 return f'<div class="group {cl}" style="{pos(col,row,w,h)}">'+''.join(cards)+'</div>'
def pill(name,note='',mark='book-open',on=False):return '<div class="pill'+(' on' if on else '')+'" data-el="cyanloop-pill"><div class="parts"><span class="mark"><span class="icon" data-icon="'+mark+'"></span></span><span class="name">'+name+'</span><span class="note">'+note+'</span></div></div>'
def listel(names,variant=''):
 return '<div class="list '+variant+'" data-el="cyanloop-list">'+''.join('<div class="item"><span class="name">'+a+'</span>'+('<span class="note">'+b+'</span>' if b else '')+'</div>' for a,b in names)+'</div>'
def stat(fig,name,note=''):return '<div class="stat" data-el="cyanloop-metric"><div class="parts"><p class="fig">'+fig+'</p><p class="name">'+name+'</p><p class="note">'+note+'</p></div></div>'
def seat(n,typ=''):return f'<div class="seat {typ}" data-ph="{n}"></div>'
def callout(t,row=6):return el('callout','callout',f'<p>{t}</p>',1,row,12,1)
def prose(t,col,row,w,h):return el('prose','prose',''.join('<p>'+p+'</p>' for p in t.split('\n')),col,row,w,h)
def frame(n,col,row,w,h):return el('frame','image-frame',seat(n),col,row,w,h)
